repo.samples.py:
"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b4', 17), ('b4', 38), ('b3', 26), ('b3', 16), ('b1', 42), ('b2', 22), ('b3', 37)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)

