"""Parsing samples from text."""
from samples import Sample


def _parse_line(line):
    batch, dose = line.split(",")
    return Sample(batch.strip(), int(dose))


def parse_samples(text):
    """Parse lines of 'batch,dose' into Sample records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out

